(function(){'use strict';var input=document.getElementById('smartTableSearch');var table=document.getElementById('smartReportTable');if(!input||!table)return;input.addEventListener('input',function(){var term=input.value.trim().toLowerCase();table.querySelectorAll('tbody .data-row').forEach(function(row){row.hidden=!!term&&row.textContent.toLowerCase().indexOf(term)===-1;});});}());
